    def __repr__(self):
        return self.__str__()

    def __call__(self, *args, **kwargs):
        return self

    def get_page(self, request, queryset):
        return self.page(request, queryset, self.page_size, self.start, self.end, self.order_by, self.reverse, self.filter)

